277	// validateSchema checks the structural legality of a schema, recursing into
278	// array items and object properties.
279	func validateSchema(schema any, path string, add func(code, message, path string)) {
280		obj, ok := schema.(map[string]any)
281		if !ok {
282			add(codeInvalidDocument, "schema must be an object", path)
283			return
284		}
285		typeRaw, hasType := obj["type"]
286		typeName, isString := typeRaw.(string)
287		if !hasType {
288			add(codeInvalidDocument, `missing required field "type"`, path)
289			return
290		}
291		if !isString {
292			add(codeInvalidDocument, `"type" must be a string`, path+"/type")
293			return
294		}
295		switch typeName {
296		case "string", "integer", "number", "boolean":
297		case "array":
298			items, has := obj["items"]
299			if !has {
300				add(codeInvalidDocument, `array schema requires "items"`, path)
301				return
302			}
303			validateSchema(items, path+"/items", add)
304		case "object":
305			if propsRaw, has := obj["properties"]; has {
306				props, ok := propsRaw.(map[string]any)
307				if !ok {
308					add(codeInvalidDocument, `"properties" must be an object`, path+"/properties")
309				} else {
310					names := make([]string, 0, len(props))
311					for name := range props {
312						names = append(names, name)
313					}
314					sort.Strings(names)
315					for _, name := range names {
316						validateSchema(props[name], path+"/properties/"+pointerEscape(name), add)
317					}
318				}
319			}
320			if reqRaw, has := obj["required"]; has {
321				req, ok := reqRaw.([]any)
322				if !ok {
323					add(codeInvalidDocument, `"required" must be an array of strings`, path+"/required")
324				} else {
325					for j, entry := range req {
326						if _, ok := entry.(string); !ok {
327							add(codeInvalidDocument, `"required" entries must be strings`, fmt.Sprintf("%s/required/%d", path, j))
328						}
329					}
330				}
331			}
332			if apRaw, has := obj["additionalProperties"]; has {
333				if _, ok := apRaw.(bool); !ok {
334					add(codeInvalidDocument, `"additionalProperties" must be a boolean`, path+"/additionalProperties")
335				}
336			}
337		default:
338			add(codeInvalidDocument, fmt.Sprintf("unknown schema type %q", typeName), path+"/type")
339		}
340	}
341	
342	// validateValue checks a value against an already-validated schema.
343	func validateValue(value, schema any, path string, add func(code, message, path string)) {
344		obj, ok := schema.(map[string]any)
345		if !ok {
346			return
347		}
348		typeName, _ := obj["type"].(string)
349		switch typeName {
350		case "string":
351			if _, ok := value.(string); !ok {
352				add(codeTypeMismatch, fmt.Sprintf("expected string, got %s", jsonTypeName(value)), path)
353			}
354		case "boolean":
355			if _, ok := value.(bool); !ok {
356				add(codeTypeMismatch, fmt.Sprintf("expected boolean, got %s", jsonTypeName(value)), path)
357			}
358		case "integer":
359			n, ok := value.(json.Number)
360			if !ok || !isJSONInteger(n) {
361				add(codeTypeMismatch, fmt.Sprintf("expected integer, got %s", jsonTypeName(value)), path)
362			}
363		case "number":
364			if _, ok := value.(json.Number); !ok {
365				add(codeTypeMismatch, fmt.Sprintf("expected number, got %s", jsonTypeName(value)), path)
366			}
367		case "array":
368			arr, ok := value.([]any)
369			if !ok {
370				add(codeTypeMismatch, fmt.Sprintf("expected array, got %s", jsonTypeName(value)), path)
371				return
372			}
373			items := obj["items"]
374			for i, el := range arr {
375				validateValue(el, items, fmt.Sprintf("%s/%d", path, i), add)
376			}
377		case "object":
378			rec, ok := value.(map[string]any)
379			if !ok {
380				add(codeTypeMismatch, fmt.Sprintf("expected object, got %s", jsonTypeName(value)), path)
381				return
382			}
383			props, _ := obj["properties"].(map[string]any)
384			additional := false
385			if ap, ok := obj["additionalProperties"].(bool); ok {
386				additional = ap
387			}
388			seen := map[string]bool{}
389			if reqRaw, ok := obj["required"].([]any); ok {
390				for _, entry := range reqRaw {
391					name, ok := entry.(string)
392					if !ok || seen[name] {
393						continue
394					}
395					seen[name] = true
396					if _, present := rec[name]; !present {
397						add(codeMissingRequiredProperty, fmt.Sprintf("missing required property %q", name), path)
398					}
399				}
400			}
401			names := make([]string, 0, len(rec))
402			for name := range rec {
403				names = append(names, name)
404			}
405			sort.Strings(names)
406			for _, name := range names {
407				childPath := path + "/" + pointerEscape(name)
408				if sub, declared := props[name]; declared {
409					validateValue(rec[name], sub, childPath, add)
410				} else if !additional {
411					add(codeUnexpectedProperty, fmt.Sprintf("unexpected property %q", name), childPath)
412				}
413			}
414		}
415	}
416	
417	// isJSONInteger reports whether a JSON number literal denotes an integer.
418	// Whole-valued forms such as 1.0 or 1e2 count as integers; fractions do not.
419	func isJSONInteger(n json.Number) bool {
420		s := n.String()
421		if _, err := strconv.ParseInt(s, 10, 64); err == nil {
422			return true
423		}
424		f, err := strconv.ParseFloat(s, 64)
425		if err != nil {
426			return false
427		}
428		return !math.IsInf(f, 0) && f == math.Trunc(f)
429	}
430	
431	func jsonTypeName(v any) string {
432		switch v.(type) {
433		case nil:
434			return "null"
435		case bool:
436			return "boolean"
437		case json.Number:
438			return "number"
439		case string:
440			return "string"
441		case []any:
442			return "array"
443		case map[string]any:
444			return "object"
445		default:
446			return "value"
447		}
448	}
