3	import (
4		"encoding/json"
5		"fmt"
6		"net/http"
7		"sort"
8		"strings"
9	)
10	
11	type orderResponse struct {
12		Valid  bool              `json:"valid"`
13		Errors []validationError `json:"errors"`
14		Order  []string          `json:"order"`
15	}
16	
17	// handleOrderConfiguration returns a deterministic topological order over
18	// the resources of an already-valid configuration document.
19	func handleOrderConfiguration(w http.ResponseWriter, r *http.Request) {
20		w.Header().Set("Content-Type", "application/json; charset=utf-8")
21		if r.Method != http.MethodPost {
22			w.Header().Set("Allow", http.MethodPost)
23			w.WriteHeader(http.StatusMethodNotAllowed)
24			_ = json.NewEncoder(w).Encode(map[string]any{
25				"error": map[string]string{"code": "method_not_allowed"},
26			})
27			return
28		}
29	
30		doc, ok := decodeConfigurationBody(w, r)
31		if !ok {
32			return
33		}
34	
35		// Dependencies are only interpreted once the base document is valid.
36		baseErrs := validateConfiguration(doc)
37		if len(baseErrs) != 0 {
38			sortValidationErrors(baseErrs)
39			writeValidation(w, http.StatusUnprocessableEntity, baseErrs)
40			return
41		}
42	
43		order, depErrs := orderConfiguration(doc)
44		if len(depErrs) != 0 {
45			sortValidationErrors(depErrs)
46			writeValidation(w, http.StatusUnprocessableEntity, depErrs)
47			return
48		}
49	
50		w.WriteHeader(http.StatusOK)
51		_ = json.NewEncoder(w).Encode(orderResponse{
52			Valid:  true,
53			Errors: []validationError{},
54			Order:  order,
55		})
56	}
57	
58	// orderConfiguration interprets the dependsOn fields of a validated document.
59	// It returns every dependency problem in one pass; dependency problems take
60	// precedence over cycle detection, and cycles take precedence over ordering.
61	func orderConfiguration(doc any) ([]string, []validationError) {
62		root := doc.(map[string]any)
63		resourceEntries := root["resources"].([]any)
64	
65		addresses := make([]string, len(resourceEntries))
66		for i, entry := range resourceEntries {
67			addresses[i] = entry.(map[string]any)["address"].(string)
68		}
69	
70		_, order, errs := resolveDependencies(resourceEntries, addresses, "/resources")
71		if len(errs) != 0 {
72			return nil, errs
73		}
74		return order, nil
