88	func TestApplyEmptyPlanSucceedsWithoutProvider(t *testing.T) {
89		res := doApply(t, Handler(), planBody(`[]`, `[]`), nil)
90		if res.status != http.StatusOK || !res.Valid || len(res.Errors) != 0 {
91			t.Fatalf("got status=%d valid=%v errors=%v", res.status, res.Valid, res.Errors)
92		}
93		if res.Applied == nil || len(*res.Applied) != 0 {
94			t.Fatalf("applied = %v, want empty array", res.Applied)
95		}
96		if res.Summary == nil || *res.Summary != (planSummary{}) {
97			t.Fatalf("summary = %+v, want zero", res.Summary)
98		}
99		if res.State == nil || len(res.State.Resources) != 0 {
100			t.Fatalf("state = %+v, want empty resources", res.State)
101		}
102	}
103	
104	func TestApplyNoopPlanSucceedsWithoutProviderAndKeepsState(t *testing.T) {
105		// a and b are identical on both sides, so the plan is all noop.
106		body := planBody(
107			`[`+resEntry("a", `["b"]`)+`,`+resEntry("b", `[]`)+`]`,
108			`[`+stateEntry("a", "t", `{}`, `["b"]`)+`,`+stateEntry("b", "t", `{}`, `[]`)+`]`)
109		provider := &recordingProvider{}
110		res := doApply(t, HandlerWithProvider(provider), body, nil)
111		if res.status != http.StatusOK || !res.Valid {
112			t.Fatalf("got status=%d valid=%v errors=%v", res.status, res.Valid, res.Errors)
113		}
114		if res.Applied == nil || len(*res.Applied) != 0 {
115			t.Fatalf("applied = %v, want empty", res.Applied)
116		}
117		if len(provider.calls) != 0 {
118			t.Fatalf("provider must not be called for noops, got %v", providerCallsSummary(provider.calls))
119		}
120		// Noop resources remain in state, address-sorted.
121		if got := stateAddresses(res); got != "a|b" {
122			t.Fatalf("state = %q, want a|b", got)
123		}
124		a := res.State.Resources[0]
125		if got := strings.Join(a.DependsOn, "|"); got != "b" {
126			t.Fatalf("a dependsOn = %v", a.DependsOn)
127		}
