130	func TestApplyChangesWithoutProviderIsUnavailable(t *testing.T) {
131		body := planBody(`[`+resEntry("a", `[]`)+`]`, `[]`)
132		res := doApply(t, Handler(), body, nil)
133		if res.status != http.StatusServiceUnavailable {
134			t.Fatalf("status = %d, want 503", res.status)
135		}
136		if res.Valid || len(res.Errors) != 1 || res.Errors[0].Code != codeProviderUnavailable {
137			t.Fatalf("unexpected payload: %+v", res)
138		}
139		if _, present := res.raw["applied"]; present {
140			t.Fatalf("503 response must not contain applied: %v", res.raw)
141		}
