173			t.Fatalf("summary = %+v", res.Summary)
174		}
175	
176		// old removed; keep adopts after (no properties); new created; c kept.
177		if got := stateAddresses(res); got != "c|keep|new" {
178			t.Fatalf("state = %q, want c|keep|new", got)
179		}
