func (b *stateBackend) handleApply(provider Provider) http.HandlerFunc {
    return func(w http.ResponseWriter, r *http.Request) {
        w.Header().Set("Content-Type", "application/json; charset=utf-8")
        if r.Method != http.MethodPost {
            rejectMethodNotAllowed(w)
            return
        }
        doc, ok := decodeConfigurationBody(w, r)
        if !ok { return }
        configRaw, expectedRevision, ok := checkStateApplyEnvelope(w, doc)
        if !ok { return }

        // validate configuration (same as plan)
        var errs []validationError
        var configResources []planResource
        var configOrder []string
        if baseErrs := validateConfiguration(configRaw); len(baseErrs) != 0 {
            errs = appendPrefixedErrors(errs, baseErrs, "/configuration")
        } else if order, depErrs := orderConfiguration(configRaw); len(depErrs) != 0 {
            errs = appendPrefixedErrors(errs, depErrs, "/configuration")
        } else {
            configResources = configurationResources(configRaw)
            configOrder = order
        }
        if len(errs) != 0 {
            sortValidationErrors(errs)
            writeValidation(w, http.StatusUnprocessableEntity, errs)
            return
        }

        unlock, acquired := tryLockState(b.path)
        if !acquired {
            writeStateError(w, http.StatusConflict, codeStateLocked, "state file is locked by another apply run")
            return
        }
        defer unlock()

        current, err := readStateFile(b.path)
        if err != nil {
            writeStateError(w, http.StatusInternalServerError, codeStateReadError, "state file cannot be read or is invalid")
            return
        }

        if expectedRevision != nil && *expectedRevision != current.revision {
            w.WriteHeader(http.StatusConflict)
            json.NewEncoder(w).Encode(stateApplyResponse{
                Valid: false,
                Errors: []validationError{{Code: codeStateConflict, Message: "expectedRevision does not match the current revision", Path: "/expectedRevision"}},
                CurrentRevision: &current.revision,
            })
            return
        }

        changes, summary := computePlan(configResources, configOrder, current.resources, current.order)
        state := seedState(current.resources)

        if len(changes) == 0 {
            // empty plan: success, revision unchanged, no write
            w.WriteHeader(http.StatusOK)
            encode stateApplyResponse{Valid: true, Errors: [], Applied: &[], Summary: summary, State: renderState(state), Revision: &current.revision}
            return
        }

        if provider == nil {
            w.WriteHeader(503)
            encode {Valid:false, Errors:[provider_unavailable...], Summary: summary, Revision: &current.revision}
            return
        }

        applied := []planChange{}
        var providerErr error
        var failIndex int
        for i, change := range changes {
            req := ChangeRequest{...}
            if err := provider.Apply(req); err != nil {
                providerErr = err
                failIndex = i
                break
            }
            applied = append(applied, change)
            applyToState(state, change)
        }

        newRevision := current.revision + 1
        if providerErr == nil || len(applied) > 0 {
            // commit
            if writeErr := writeStateFile(b.path, newRevision, state); writeErr != nil {
                w.WriteHeader(500)
                encode {Valid:false, Errors:[{state_write_error, ...}], Applied: &applied, Summary: summary, State: renderState(state), Revision: &current.revision}
                return
            }
        }

        if providerErr != nil {
            // partial: file committed with revision+1 if applied>0; else unchanged
            rev := current.revision
            if len(applied) > 0 { rev = newRevision }
            w.WriteHeader(502)
            encode {Valid:false, Errors:[{provider_error, providerErr.Error(), /changes/i}], Applied: &applied, Summary: summary, State: renderState(state), Revision: &rev}
            return
        }

        w.WriteHeader(200)
        encode {Valid:true, Errors:[], Applied:&applied, Summary:summary, State: renderState(state), Revision: &newRevision}
    }
}
```

