// value. Whole-valued forms such as 1.0 or 1e2 count as integers, matching
// the configuration validator's notion of integer.
func nonNegativeInt64(v any) (int64, bool) {
	n, ok := v.(json.Number)
	if !ok {
		return 0, false
	}
	s := n.String()
	if i, err := strconv.ParseInt(s, 10, 64); err == nil {
		return i, i >= 0
